<?php
require_once __DIR__.'/_common.php';$current_slug='data-anak';require_once ROOT_PATH.'/includes/auth-guard.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$format=$_GET['format']??'csv';$params=[];$where='';if($id){$where=' WHERE a.id_anak=?';$params[]=$id;}
$stmt=$pdo->prepare("SELECT a.nik,a.nama,a.tanggal_lahir,a.jenis_kelamin,a.alamat,p.nama_posyandu,o.nama_ayah,o.nama_ibu,o.no_telepon,o.alamat AS alamat_wali FROM anak a JOIN posyandu p ON p.id_posyandu=a.id_posyandu JOIN orangtua o ON o.id_orangtua=a.id_orangtua$where ORDER BY a.nama");$stmt->execute($params);$rows=$stmt->fetchAll();if(!$rows){set_flash('warning','Tidak ada data anak untuk diekspor.');redirect(data_anak_url());}
if($format==='print'){
?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Data Anak - <?= e(APP_NAME) ?></title><link href="<?= asset('css/bootstrap.min.css') ?>" rel="stylesheet"><style>body{padding:32px}@media print{.no-print{display:none}}</style></head><body><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3">Data Anak</h1><p>Diekspor dari <?= e(APP_NAME) ?> · <?= date('d/m/Y H:i') ?></p></div><button class="btn btn-primary no-print" onclick="window.print()">Cetak / Simpan PDF</button></div><div class="table-responsive"><table class="table table-bordered table-sm"><thead><tr><th>NIK</th><th>Nama</th><th>Tgl lahir</th><th>JK</th><th>Posyandu</th><th>Ayah</th><th>Ibu</th><th>Telepon</th><th>Alamat</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['nik']) ?></td><td><?= e($r['nama']) ?></td><td><?= e($r['tanggal_lahir']) ?></td><td><?= $r['jenis_kelamin']==='L'?'L':'P' ?></td><td><?= e($r['nama_posyandu']) ?></td><td><?= e($r['nama_ayah']) ?></td><td><?= e($r['nama_ibu']) ?></td><td><?= e($r['no_telepon']) ?></td><td><?= e($r['alamat']) ?></td></tr><?php endforeach; ?></tbody></table></div><script>window.addEventListener('load',()=>window.print())</script></body></html><?php exit;
}
$filename='Data_Anak_'.date('Ymd_His').'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');fprintf($out,chr(0xEF).chr(0xBB).chr(0xBF));fputcsv($out,['NIK','Nama Anak','Tanggal Lahir','Jenis Kelamin','Posyandu','Nama Ayah','Nama Ibu','Telepon Orang Tua/Wali','Alamat Anak','Alamat Orang Tua/Wali']);foreach($rows as $r)fputcsv($out,[$r['nik'],$r['nama'],$r['tanggal_lahir'],$r['jenis_kelamin']==='L'?'Laki-laki':'Perempuan',$r['nama_posyandu'],$r['nama_ayah'],$r['nama_ibu'],$r['no_telepon'],$r['alamat'],$r['alamat_wali']]);fclose($out);exit;
